/**
 * DateRangePicker.RangeCalendar: the popup's month grid, Calendar's anatomy with the range's cells, on Zag's date-picker machine in range mode.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/date-range-picker.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/date-picker'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Keyed,
  claimSlot,
  createCell,
  createDerived,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  watchEffect,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/date-range-picker.module.css'
import Button from './Button'
import type { CalendarDate, CalendarMessages } from './Calendar'
import type { DateRange } from './DateRangePicker'

export interface DateRangePickerRangeCalendarProps {
  /**
   * The committed range, which the grid starts from.
   */
  value: DateRange | null
  minValue?: CalendarDate
  maxValue?: CalendarDate
  isDateUnavailable?: (date: CalendarDate) => boolean
  locale?: string
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  disabled: boolean
  messages: CalendarMessages
  /**
   * The grid's name, before the month on screen.
   */
  label: string
  onCommit?: (range: DateRange) => void
  onAnchorChange?: (anchored: boolean) => void
}

/** DateRangePicker.RangeCalendar: the popup's month grid, Calendar's anatomy with the range's cells, on Zag's date-picker machine in range mode. */
export default function DateRangePickerRangeCalendar(
  given: DateRangePickerRangeCalendarProps,
): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const uid = createUniqueId()
    const travel = createCell('next')
    const shownMonth = createCell('')
    const restoring = createCell(false)
    const language = createDerived(() => props.locale ?? 'en-US')
    const english = createDerived(() => language.value.toLowerCase().startsWith('en'))
    const zone = createDerived(() => Intl.DateTimeFormat().resolvedOptions().timeZone)
    const dayName = createDerived(
      () => (date: zag.DateValue, text: string, today: boolean, selected: boolean) => {
        if (!english.value) return text
        const said = today
          ? selected
            ? `Today, ${text} selected`
            : `Today, ${text}`
          : selected
            ? `${text} selected`
            : text
        if (props.minValue !== undefined && date.compare(props.minValue) === 0)
          return `${said}, First available date`
        if (props.maxValue !== undefined && date.compare(props.maxValue) === 0)
          return `${said}, Last available date`
        return said
      },
    )
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          inline: true,
          selectionMode: 'range' as const,
          locale: language.value,
          timeZone: zone.value,
          defaultValue: props.value === null ? undefined : [props.value.start, props.value.end],
          min: props.minValue,
          max: props.maxValue,
          startOfWeek: props.firstDayOfWeek,
          disabled: props.disabled,
          isDateUnavailable:
            props.isDateUnavailable === undefined
              ? undefined
              : (date) => props.isDateUnavailable?.(date as zag.CalendarDate) === true,
          onValueChange: (details) => {
            void (restoring.value
              ? (restoring.value = false)
              : details.value.length === 2 &&
                props.onCommit?.({
                  start: details.value[0] as zag.CalendarDate,
                  end: details.value[1] as zag.CalendarDate,
                }))
          },
          onVisibleRangeChange: (details) => {
            void ((travel.value =
              shownMonth.value !== '' && details.visibleRange.start.toString() < shownMonth.value
                ? 'previous'
                : 'next'),
            (shownMonth.value = details.visibleRange.start.toString()))
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const title = createDerived(() => api.value.visibleRangeText.start)
    const named = createDerived(() => [props.label, title.value].filter(Boolean).join(', '))
    const previewing = createDerived(
      () =>
        api.value.value.length === 1 &&
        api.value.weeks.some((week) =>
          week.some((date) => api.value.getDayTableCellState({ value: date }).inHoveredRange),
        ),
    )
    const dayOf = createDerived(() => (date: zag.DateValue) => {
      const cell = api.value.getDayTableCellState({ value: date })
      const off = props.disabled || cell.invalid
      const refused = props.isDateUnavailable?.(date as zag.CalendarDate) === true
      const start = previewing.value ? cell.firstInHoveredRange : cell.firstInRange
      const end = previewing.value
        ? cell.lastInHoveredRange
        : api.value.value.length === 1
          ? cell.firstInRange
          : cell.lastInRange
      const inside = (previewing.value ? cell.inHoveredRange : cell.inRange) || start || end
      return {
        date,
        cell,
        off,
        unavailable: refused,
        outside: cell.outsideRange,
        selectable: !off && !refused,
        inside,
        start,
        end,
        middle: inside && !start && !end,
        name: dayName.value(date, cell.valueText, cell.today, inside),
      }
    })
    const weeks = createDerived(() =>
      api.value.weeks.map((week) => week.map((date) => dayOf.value(date))),
    )
    const cancel = createDerived(() => (): void => {
      if (api.value.value.length !== 1) return
      const at = api.value.focusedValue
      restoring.value = true
      if (props.value === null) api.value.clearValue({ focus: false })
      else api.value.setValue([props.value.start, props.value.end])
      api.value.setFocusedValue(at)
    })
    const effect1 = () => {
      shownMonth.value = api.value.visibleRange.start.toString()
    }
    onMount(effect1)
    const effect2 = () => {
      props.onAnchorChange?.(api.value.value.length === 1)
    }
    watchEffect(
      createMemo(() => api.value.value.length),
      effect2,
      true,
    )
    return (
      <div
        {...mergeParts(api.value.getContentProps(), {
          class: styles.root,
          hidden: undefined,
          tabindex: undefined,
          'data-state': undefined,
          role: 'application',
          'aria-label': named.value,
        })}
      >
        {/* header */}
        <div class={styles.header}>
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="previous"
            label={props.messages.previousMonth}
            disabled={props.disabled || api.value.getPrevTriggerProps().disabled === true}
            onClick={() => api.value.goToPrev()}
          />
          {/* title */}
          <span class={styles.title} aria-live="polite">
            {title.value}
          </span>
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="next"
            label={props.messages.nextMonth}
            disabled={props.disabled || api.value.getNextTriggerProps().disabled === true}
            onClick={() => api.value.goToNext()}
          />
        </div>
        {/* grid */}
        <Keyed by={api.value.visibleRange.start.toString()}>
          {() => (
            <table
              {...mergeParts(api.value.getTableProps(), {
                class: styles.grid,
                tabindex: undefined,
                'aria-label': named.value,
                'data-travel': travel.value,
                onkeydown: ($event: KeyboardEvent) => $event.key === 'Escape' && cancel.value(),
              })}
            >
              <thead aria-hidden="true">
                <tr>
                  <Each of={api.value.weekDays} by={(weekday) => weekday.long} renew>
                    {(weekday) => (
                      <th scope="col" aria-label={weekday.long}>
                        <span aria-hidden="true">{weekday.short}</span>
                      </th>
                    )}
                  </Each>
                </tr>
              </thead>
              <tbody>
                <Each of={weeks.value} by={(_week, at) => at} renew>
                  {(week) => (
                    <tr>
                      <Each of={week} by={(day) => day.date.toString()} renew>
                        {(day) => (
                          <>
                            {day.outside ? (
                              <td />
                            ) : (
                              <td
                                class={styles.cell}
                                role="gridcell"
                                aria-disabled={!day.selectable ? 'true' : undefined}
                                aria-selected={day.inside ? 'true' : undefined}
                              >
                                {/* day */}
                                <div
                                  {...mergeParts(
                                    api.value.getDayTableCellTriggerProps({ value: day.date }),
                                    {
                                      class: styles.day,
                                      'data-calendar-part': 'day',
                                      'aria-label': day.name,
                                      'aria-current': day.cell.today ? 'date' : undefined,
                                      tabindex: day.off ? undefined : day.cell.focused ? 0 : -1,
                                      'data-selected': undefined,
                                      'data-range-start': day.start ? '' : undefined,
                                      'data-range-middle': day.middle ? '' : undefined,
                                      'data-range-end': day.end ? '' : undefined,
                                      'data-today': day.cell.today ? '' : undefined,
                                      'data-unavailable': day.unavailable ? '' : undefined,
                                      'data-disabled': day.off ? '' : undefined,
                                      onfocus: () => api.value.setFocusedValue(day.date),
                                      onkeydown: ($event: KeyboardEvent) =>
                                        $event.key === ' ' &&
                                        day.selectable &&
                                        ($event.preventDefault(),
                                        ($event.currentTarget as HTMLElement).click()),
                                    },
                                  )}
                                >
                                  {day.date.day}
                                </div>
                              </td>
                            )}
                          </>
                        )}
                      </Each>
                    </tr>
                  )}
                </Each>
              </tbody>
            </table>
          )}
        </Keyed>
      </div>
    )
  })
}
